class Account {
  #balance = 0;

  get balance() {           // read with account.balance (no parentheses)
    return this.#balance;
  }

  deposit(amount) {
    if (amount <= 0) throw new Error("amount must be positive");
    this.#balance += amount;
  }
}

const account = new Account();
account.deposit(50);
account.balance;       // 50
account.balance = 999; // no setter: ignored, or a TypeError in strict mode
// account.#balance    // SyntaxError outside the class
